#!/usr/bin/env python3
# Декодер whitespace-стего: пробел=0, таб=1, 8 бит на символ
data = open("message.txt", "rb").read().decode()
bits = ""
for line in data.split("\n"):
    if not line:
        continue
    tail = line[1:]
    for ch in tail:
        if ch == " ":
            bits += "0"
        elif ch == "\t":
            bits += "1"
out = bytes(int(bits[i:i+8], 2) for i in range(0, len(bits) - 7, 8))
print(out.decode())
